"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { AppShell } from "../ui/app-shell";
import { getSupabaseBrowserClient } from "../../lib/supabase/client";
import { usePlayerData } from "../../lib/use-player-data";

type Player={id:string;display_name:string|null;email:string};
type Intake={player_id:string;primary_goal:string;outcome_target:string;weekly_golf_minutes:number;weekly_vector_minutes:number;sessions_per_week:number;available_days:string[];facilities:string[];competition_dates:string;recovery_constraints:string;consent_confirmed:boolean};
type Programme={id:string;player_id:string;coach_id:string;title:string;primary_goal:string;start_date:string;status:"draft"|"published"|"completed"|"archived";golf_minutes_per_week:number;vector_minutes_per_week:number;current_week:number};
type Week={id:string;week_number:number;phase:"Measure"|"Build"|"Stabilise"|"Transfer"|"Perform";focus:string;golf_minutes:number;vector_minutes:number;review_type:string|null;coach_notes:string|null;status:string};
const days=["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"];
const facilities=["Driving range","Short-game area","Putting green","Golf course","Gym","Home equipment","Launch monitor"];
const blankIntake=(id:string):Intake=>({player_id:id,primary_goal:"",outcome_target:"",weekly_golf_minutes:180,weekly_vector_minutes:60,sessions_per_week:3,available_days:[],facilities:[],competition_dates:"",recovery_constraints:"",consent_confirmed:false});
const weekPlan=[
  [1,"Measure","Baseline, success definitions and representative testing","Initial measure"],[2,"Measure","Confirm priorities and set the programme route","Priority review"],
  [3,"Build","Develop the primary technical and movement capacities",null],[4,"Build","Progress the selected solution without losing strike or intent","Progress review"],[5,"Build","Consolidate the highest-value practice pattern",null],
  [6,"Stabilise","Improve repeatability across changing targets","Stability review"],[7,"Stabilise","Retain the solution as constraints increase","Mid-block review"],[8,"Stabilise","Validate the pattern without coaching aids","Retest"],
  [9,"Transfer","Move the skill into random and on-course tasks","Transfer review"],[10,"Transfer","Test strategy, consequence and competitive routines","Competition review"],
  [11,"Perform","Reduce volume and protect quality for performance","Readiness review"],[12,"Perform","Final performance test and next-cycle decision","Final retest"],
] as const;

export default function ProgrammePage(){
  const{profile}=usePlayerData();const[players,setPlayers]=useState<Player[]>([]),[selectedId,setSelectedId]=useState(""),[intake,setIntake]=useState<Intake|null>(null),[programme,setProgramme]=useState<Programme|null>(null),[weeks,setWeeks]=useState<Week[]>([]),[message,setMessage]=useState("");
  const canCoach=profile?.role==="coach"||profile?.role==="admin";const targetId=canCoach?selectedId:profile?.id||"";
  const loadPlayers=useCallback(async()=>{const sb=getSupabaseBrowserClient();if(!sb||!profile||!canCoach)return;const{data:links}=await sb.from("coach_player_links").select("player_id").eq("coach_id",profile.id);const ids=(links||[]).map(link=>link.player_id);if(!ids.length){setPlayers([]);return}const{data}=await sb.from("profiles").select("id,display_name,email").in("id",ids).order("display_name");const linked=(data||[])as Player[];setPlayers(linked);setSelectedId(current=>current&&linked.some(player=>player.id===current)?current:linked[0]?.id||"")},[profile,canCoach]);
  const loadProgramme=useCallback(async()=>{const sb=getSupabaseBrowserClient();if(!sb||!targetId)return;const[intakeResult,programmeResult]=await Promise.all([sb.from("programme_intakes").select("*").eq("player_id",targetId).maybeSingle(),sb.from("programmes").select("*").eq("player_id",targetId).in("status",canCoach?["draft","published","completed"]:["published","completed"]).order("created_at",{ascending:false}).limit(1).maybeSingle()]);setIntake((intakeResult.data as Intake|null)||blankIntake(targetId));const found=programmeResult.data as Programme|null;setProgramme(found);if(found){const{data}=await sb.from("programme_weeks").select("*").eq("programme_id",found.id).order("week_number");setWeeks((data||[])as Week[])}else setWeeks([])},[targetId,canCoach]);
  useEffect(()=>{const timer=setTimeout(()=>void loadPlayers(),0);return()=>clearTimeout(timer)},[loadPlayers]);useEffect(()=>{const timer=setTimeout(()=>void loadProgramme(),0);return()=>clearTimeout(timer)},[loadProgramme]);
  const saveIntake=async(event:React.FormEvent)=>{event.preventDefault();const sb=getSupabaseBrowserClient();if(!sb||!intake||!profile||canCoach)return;const{error}=await sb.from("programme_intakes").upsert({...intake,completed_at:new Date().toISOString(),updated_at:new Date().toISOString()});setMessage(error?error.message:"Programme questionnaire saved for your coach.")};
  const createProgramme=async()=>{const sb=getSupabaseBrowserClient();if(!sb||!profile||!targetId||!intake)return;const start=new Date();start.setDate(start.getDate()+((8-start.getDay())%7));const{data,error}=await sb.from("programmes").insert({player_id:targetId,coach_id:profile.id,primary_goal:intake.primary_goal||"Improve scoring performance",start_date:start.toISOString().slice(0,10),golf_minutes_per_week:intake.weekly_golf_minutes,vector_minutes_per_week:intake.weekly_vector_minutes}).select("*").single();if(error||!data){setMessage(error?.message||"Could not create programme.");return}const rows=weekPlan.map(([week_number,phase,focus,review_type])=>({programme_id:data.id,week_number,phase,focus,golf_minutes:intake.weekly_golf_minutes,vector_minutes:intake.weekly_vector_minutes,review_type,status:"draft"}));const{error:weekError}=await sb.from("programme_weeks").insert(rows);setMessage(weekError?weekError.message:"12-week programme created as a coach draft.");await loadProgramme()};
  const updateProgramme=async(changes:Partial<Programme>)=>{const sb=getSupabaseBrowserClient();if(!sb||!programme)return;const publish=changes.status==="published"?{published_at:new Date().toISOString()}:{};const{error}=await sb.from("programmes").update({...changes,...publish,updated_at:new Date().toISOString()}).eq("id",programme.id);if(!error&&changes.status==="published")await sb.from("programme_weeks").update({status:"published",updated_at:new Date().toISOString()}).eq("programme_id",programme.id);setMessage(error?error.message:"Programme updated.");if(!error)await loadProgramme()};
  const updateWeek=async(id:string,changes:Partial<Week>)=>{const sb=getSupabaseBrowserClient();if(!sb)return;const{error}=await sb.from("programme_weeks").update({...changes,updated_at:new Date().toISOString()}).eq("id",id);setMessage(error?error.message:"Week updated.");if(!error)await loadProgramme()};
  const totalGolf=useMemo(()=>weeks.reduce((sum,week)=>sum+week.golf_minutes,0),[weeks]),totalVector=useMemo(()=>weeks.reduce((sum,week)=>sum+week.vector_minutes,0),[weeks]);
  return <AppShell active="programme"><header className="page-heading"><div><p className="eyebrow">Package 7F.1 · Programme foundation</p><h1>Build the next twelve weeks.</h1><p>TEST → PRIORITISE → PROGRAMME → PROGRESS → TRANSFER → RETEST, with every minute visible and every Vector allocation tied to an established movement need.</p></div></header>{message&&<div className="success-banner" role="status">{message}</div>}{canCoach&&<section className="programme-player"><label>Programme player<select value={selectedId} onChange={event=>setSelectedId(event.target.value)}><option value="">Choose linked player</option>{players.map(player=><option value={player.id} key={player.id}>{player.display_name||player.email}</option>)}</select></label><span>{programme?`${programme.status} programme`:"No programme yet"}</span></section>}{targetId&&intake&&!canCoach&&<form className="intake-card" onSubmit={saveIntake}><div className="section-heading"><div><p className="eyebrow">Player questionnaire</p><h2>Make the plan fit real life.</h2></div></div><div className="intake-grid"><label>Primary goal<input value={intake.primary_goal} onChange={event=>setIntake({...intake,primary_goal:event.target.value})} required/></label><label>12-week outcome target<input value={intake.outcome_target} onChange={event=>setIntake({...intake,outcome_target:event.target.value})}/></label><label>Golf practice minutes per week<input type="number" min="0" value={intake.weekly_golf_minutes} onChange={event=>setIntake({...intake,weekly_golf_minutes:Number(event.target.value)})}/></label><label>Vector minutes per week<input type="number" min="0" value={intake.weekly_vector_minutes} onChange={event=>setIntake({...intake,weekly_vector_minutes:Number(event.target.value)})}/></label><label>Sessions per week<input type="number" min="1" max="14" value={intake.sessions_per_week} onChange={event=>setIntake({...intake,sessions_per_week:Number(event.target.value)})}/></label><label>Competition dates<textarea value={intake.competition_dates} onChange={event=>setIntake({...intake,competition_dates:event.target.value})}/></label><label className="wide">Recovery, pain or schedule constraints<textarea value={intake.recovery_constraints} onChange={event=>setIntake({...intake,recovery_constraints:event.target.value})}/></label></div><fieldset><legend>Available days</legend>{days.map(day=><label key={day}><input type="checkbox" checked={intake.available_days.includes(day)} onChange={()=>setIntake({...intake,available_days:intake.available_days.includes(day)?intake.available_days.filter(item=>item!==day):[...intake.available_days,day]})}/>{day.slice(0,3)}</label>)}</fieldset><fieldset><legend>Facilities available</legend>{facilities.map(item=><label key={item}><input type="checkbox" checked={intake.facilities.includes(item)} onChange={()=>setIntake({...intake,facilities:intake.facilities.includes(item)?intake.facilities.filter(value=>value!==item):[...intake.facilities,item]})}/>{item}</label>)}</fieldset><label className="consent"><input type="checkbox" checked={intake.consent_confirmed} onChange={event=>setIntake({...intake,consent_confirmed:event.target.checked})} required/>I confirm this information can be used by my coach to build and adjust my programme.</label><button className="primary-action">Save questionnaire</button></form>}{canCoach&&targetId&&intake&&!programme&&<section className="programme-empty"><p className="eyebrow">Ready to build</p><h2>{intake.primary_goal||"Player questionnaire not completed"}</h2><p>{intake.weekly_golf_minutes} golf minutes + {intake.weekly_vector_minutes} Vector minutes per week · {intake.sessions_per_week} sessions</p><button className="primary-action" onClick={createProgramme} disabled={!intake.primary_goal}>Create 12-week draft</button></section>}{programme&&<><section className="programme-summary"><div><span>Status</span><strong>{programme.status}</strong></div><div><span>Golf allocation</span><strong>{totalGolf} min</strong></div><div><span>Vector allocation</span><strong>{totalVector} min</strong></div><div><span>Start</span><strong>{new Date(programme.start_date+"T12:00:00").toLocaleDateString("en-GB")}</strong></div>{canCoach&&<button className="primary-action" onClick={()=>updateProgramme({status:programme.status==="published"?"draft":"published"})}>{programme.status==="published"?"Return to draft":"Publish programme"}</button>}</section><section className="programme-timeline">{weeks.map(week=><article className={`programme-week phase-${week.phase.toLowerCase()}`} key={week.id}><header><span>Week {String(week.week_number).padStart(2,"0")}</span><b>{week.phase}</b>{week.review_type&&<small>{week.review_type}</small>}</header><div><h2>{week.focus}</h2>{canCoach?<><label>Weekly focus<input value={week.focus} onChange={event=>setWeeks(current=>current.map(item=>item.id===week.id?{...item,focus:event.target.value}:item))} onBlur={event=>updateWeek(week.id,{focus:event.target.value})}/></label><div className="minute-fields"><label>Golf minutes<input type="number" min="0" value={week.golf_minutes} onChange={event=>setWeeks(current=>current.map(item=>item.id===week.id?{...item,golf_minutes:Number(event.target.value)}:item))} onBlur={event=>updateWeek(week.id,{golf_minutes:Number(event.target.value)})}/></label><label>Vector minutes<input type="number" min="0" value={week.vector_minutes} onChange={event=>setWeeks(current=>current.map(item=>item.id===week.id?{...item,vector_minutes:Number(event.target.value)}:item))} onBlur={event=>updateWeek(week.id,{vector_minutes:Number(event.target.value)})}/></label></div><label>Coach note<textarea defaultValue={week.coach_notes||""} onBlur={event=>updateWeek(week.id,{coach_notes:event.target.value})}/></label></>:<><p>{week.golf_minutes} golf minutes · {week.vector_minutes} Vector minutes</p>{week.coach_notes&&<blockquote>{week.coach_notes}</blockquote>}</>}</div></article>)}</section></>}{!targetId&&<div className="empty-state compact"><h2>Select a linked player</h2><p>Choose a player to build or edit their 12-week programme.</p></div>}</AppShell>;
}
